import test from 'node:test';
import assert from 'node:assert/strict';
import {
  checkpointFocusSession,
  createFocusSession,
  finishFocusSession,
  focusProgress,
  formatFocusDuration,
  pauseFocusSession,
  recoverFocusSession,
  resumeFocusSession
} from '../src/focus.js';

const task = { id: 'task-1', title: 'Write project brief' };
const startedAt = '2026-09-24T12:00:00.000Z';

test('starts a 25-minute session and only counts its running elapsed time', () => {
  const session = createFocusSession(task, 25, { id: 'focus-1', now: startedAt });
  assert.equal(session.durationMilliseconds, 25 * 60_000);
  const checkpoint = checkpointFocusSession(session, '2026-09-24T12:03:12.500Z');
  assert.deepEqual(focusProgress(checkpoint, '2026-09-24T12:03:12.500Z'), { focusedMilliseconds: 192500, remainingMilliseconds: 1307500, complete: false });
  assert.equal(formatFocusDuration(192500), '3m 12s');
});

test('pauses and resumes without counting the paused interval', () => {
  const session = createFocusSession(task, 25, { id: 'focus-2', now: startedAt });
  const paused = pauseFocusSession(session, '2026-09-24T12:04:00.000Z');
  assert.equal(paused.status, 'paused');
  assert.equal(paused.focusedMilliseconds, 240000);
  assert.equal(focusProgress(paused, '2026-09-24T12:15:00.000Z').focusedMilliseconds, 240000);
  const resumed = resumeFocusSession(paused, '2026-09-24T12:15:00.000Z');
  assert.equal(focusProgress(resumed, '2026-09-24T12:17:30.000Z').focusedMilliseconds, 390000);
});

test('reload recovery deliberately pauses a running session without adding reload time', () => {
  const session = createFocusSession(task, 25, { id: 'focus-3', now: startedAt });
  const checkpoint = checkpointFocusSession(session, '2026-09-24T12:02:00.000Z');
  const recovered = recoverFocusSession(checkpoint);
  assert.deepEqual(recovered, { ...checkpoint, status: 'paused', lastResumedAt: null });
  assert.equal(focusProgress(recovered, '2026-09-24T14:02:00.000Z').focusedMilliseconds, 120000);
});

test('finishes early or cancels with a task-title snapshot and actual focused time', () => {
  const session = createFocusSession(task, 25, { id: 'focus-4', now: startedAt });
  const early = finishFocusSession(session, 'finishedEarly', '2026-09-24T12:06:07.000Z');
  const cancelled = finishFocusSession(session, 'cancelled', '2026-09-24T12:01:03.000Z');
  assert.equal(early.taskTitle, 'Write project brief');
  assert.equal(early.focusedMilliseconds, 367000);
  assert.equal(cancelled.outcome, 'cancelled');
  assert.equal(cancelled.focusedMilliseconds, 63000);
});

test('records a completed session at its full duration', () => {
  const session = createFocusSession(task, 25, { id: 'focus-5', now: startedAt });
  const completed = finishFocusSession(session, 'completed', '2026-09-24T12:30:00.000Z');
  assert.equal(completed.focusedMilliseconds, 1500000);
  assert.equal(completed.outcome, 'completed');
  assert.throws(() => finishFocusSession(session, 'completed', '2026-09-24T12:05:00.000Z'), /Only a completed timer/);
});
import assert from 'node:assert/strict';
import http from 'node:http';
import test from 'node:test';
import { readdir } from 'node:fs/promises';
import { createFocusDeskServer, handleRequest } from '../server.mjs';

async function browserModules() {
  const sourceDirectory = new URL('../src/', import.meta.url);
  const modules = (await readdir(sourceDirectory))
    .filter(file => file.endsWith('.js'))
    .map(file => `/src/${file}`)
    .sort();
  assert.ok(modules.length > 0, 'expected browser modules in src');
  return modules;
}

function handle(path) {
  return new Promise(resolve => {
    const response = {
      writeHead(statusCode, headers) { this.statusCode = statusCode; this.headers = headers; },
      end(body) { resolve({ body: body?.toString('utf8') ?? '', headers: this.headers, statusCode: this.statusCode }); }
    };
    handleRequest({ method: 'GET', url: path }, response);
  });
}

function request(port, path) {
  return new Promise((resolve, reject) => {
    const request = http.get({ hostname: '127.0.0.1', port, path }, response => {
      const chunks = [];
      response.on('data', chunk => chunks.push(chunk));
      response.on('end', () => resolve({
        body: Buffer.concat(chunks).toString('utf8'),
        headers: response.headers,
        statusCode: response.statusCode
      }));
    });
    request.on('error', reject);
  });
}

test('the server routes every browser module', async () => {
  for (const modulePath of await browserModules()) {
    const response = await handle(modulePath);
    assert.equal(response.statusCode, 200, `${modulePath} should be available`);
    assert.match(response.headers['Content-Type'], /^text\/javascript;/, `${modulePath} should have a JavaScript content type`);
    assert.notEqual(response.body, '', `${modulePath} should have a response body`);
  }
});

test('the local server serves every browser module', async t => {
  const server = createFocusDeskServer();
  try {
    await new Promise((resolve, reject) => {
      server.once('error', reject);
      server.listen(0, '127.0.0.1', resolve);
    });
  } catch (error) {
    if (error.code === 'EPERM') {
      t.skip('loopback listeners are restricted in this environment');
      return;
    }
    throw error;
  }
  t.after(() => new Promise(resolve => server.close(resolve)));

  const { port } = server.address();
  for (const modulePath of await browserModules()) {
    const response = await request(port, modulePath);
    assert.equal(response.statusCode, 200, `${modulePath} should be available`);
    assert.match(response.headers['content-type'], /^text\/javascript;/, `${modulePath} should have a JavaScript content type`);
    assert.notEqual(response.body, '', `${modulePath} should have a response body`);
  }
});
import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const port = Number(process.env.PORT || 4173);
export const APP_MODULE_PATHS = ['app', 'domain', 'focus', 'daily-plan', 'storage'].map(name => `/src/${name}.js`);
const files = new Map([
  ['/', ['index.html', 'text/html']],
  ['/styles.css', ['styles.css', 'text/css']],
  ...APP_MODULE_PATHS.map(path => [path, [path.slice(1), 'text/javascript']])
]);

export async function handleRequest(req, res) {
  const file = files.get(new URL(req.url, 'http://localhost').pathname);
  if (!file || !['GET', 'HEAD'].includes(req.method)) { res.writeHead(404); res.end('Not found'); return; }
  try {
    const body = await readFile(new URL(file[0], import.meta.url));
    res.writeHead(200, { 'Content-Type': `${file[1]}; charset=utf-8`, 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' });
    res.end(req.method === 'HEAD' ? undefined : body);
  } catch { res.writeHead(500); res.end('Unable to load this page'); }
}

export function createFocusDeskServer() {
  return http.createServer(handleRequest);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  createFocusDeskServer().listen(port, '127.0.0.1', () => console.log(`Focus Desk is available at http://127.0.0.1:${port}`));
}

