    URL: { createObjectURL: () => 'blob:failed-export', revokeObjectURL: url => revoked.push(url) }
  }), /blocked/);
  assert.equal(link.removeCount, 1);
  assert.deepEqual(revoked, ['blob:failed-export']);
});
